    add(/(measured|using|by (the|a|an)? ?\w+|determined|calculated|recorded|as the)/i.test(text) || (f.method && has(f.method)) ? true : false, 'It says how the dependent variable is measured.', 'Say how you will measure the dependent variable, e.g. "measured as the volume of oxygen produced in 2 minutes".');
    add(/\b[A-Z][a-z]+ [a-z]{3,}\b/.test(text) || (f.organism && has(f.organism)) ? true : false, 'The organism or biological system is specified (ideally with its scientific name).', 'Specify the organism or system, with its scientific name (e.g. catalase from Solanum tuberosum).');
