    if (risky) rows.push(['no', 'Feasibility and ethics: "' + E(risky[0]) + '" needs your teacher\'s approval under IB and school policy, or a safer alternative.']);
    var level = score >= 7 ? ['Strong', 'ok', 'Focused, measurable and specific: ready to discuss with your supervisor.'] : score >= 5 ? ['Developing', 'info', 'A good start: fix the items marked ✘ or ◐ to make it specific.'] : ['Broad', 'warn', 'This is still a topic rather than a research question.'];
    return { rows: rows, score: score, max: 8, level: level };
