    var upd = function () { var t = RH.get('rq.text', ''), f = RH.get('rq.fields', {}); m.querySelector('#rq-res').innerHTML = t ? rqResult(t, f) : ''; var c = IA.rqCheck(t, f); if (RH.owner && RH.get('rq.quality') !== c.score) { RH.p.data.rq.quality = c.score; RH.dirty(); } };
    var drawVs = function () { m.querySelector('#rq-vs').innerHTML = vs.length ? '<div class="scroll"><table class="dt"><thead><tr><th>#</th><th>Question</th><th>Quality</th><th>Saved</th><th></th></tr></thead><tbody>' + vs.map(function (v, i) { return '<tr><td>' + (i + 1) + '</td><td class="small">' + E(v.text) + '</td><td>' + v.score + '/8</td><td class="small">' + RH.date(v.at, true) + '</td><td>' + (i ? '<button class="btn xs" data-cmp="' + i + '" type="button">Compare with v' + i + '</button>' : '') + '</td></tr><tr hidden data-cmpo="' + i + '"><td colspan="5" class="rh-diff small"></td></tr>'; }).join('') + '</tbody></table></div>' : '<p class="small muted">Keep versions as your question improves, to see how it developed.</p>';
      m.querySelectorAll('[data-cmp]').forEach(function (b) { b.onclick = function () { var i = +b.dataset.cmp, row = m.querySelector('[data-cmpo="' + i + '"]'); row.hidden = !row.hidden; row.firstChild.innerHTML = RH.diff(vs[i - 1].text, vs[i].text); }; }); };
    m.querySelectorAll('[data-rq]').forEach(function (i) { i.oninput = function () { var f = RH.get('rq.fields', {}); f[i.dataset.rq] = i.value; RH.set('rq.fields', f); upd(); }; });
    var bld = m.querySelector('#rq-build'); if (bld) bld.onclick = function () { var t = rqBuild(RH.get('rq.fields', {})); RH.set('rq.text', t); m.querySelector('[data-path="rq.text"]').value = t; upd(); };
    var keep = m.querySelector('#rq-keep'); if (keep) keep.onclick = function () { var t = RH.get('rq.text', '').trim(); if (!t) return; vs.push({ text: t, at: new Date().toISOString(), score: IA.rqCheck(t, RH.get('rq.fields', {})).score }); RH.set('rq.versions', vs); drawVs(); RH.toast('Version kept'); };
