      var unitSteps = st.filter(function (s) { return UNIT.test(s); }).length;
      rows.push([st.length >= 6 ? 'ok' : st.length >= 4 ? 'mid' : 'no', st.length + ' procedure steps.' + (st.length < 6 ? ' Most reproducible methods need 6 or more precise steps.' : '')]);
