      rows.push([/(°c|temperature|water bath)/i.test(all + ' ' + (x.materials || '')) ? 'ok' : 'mid', 'Temperature control is stated (it affects almost every biological rate).']);
      rows.push([/(time|min|s\b|seconds|stopwatch|timer)/i.test(all) ? 'ok' : 'no', 'Timings are stated.']);
      var dv = String((v.dv || {}).name || '').toLowerCase().split(/[ (]/)[0]; rows.push([dv && all.toLowerCase().indexOf(dv) >= 0 ? 'ok' : 'mid', 'A step says exactly how the dependent variable is measured.']);
      var lv = String((v.iv || {}).levels || '').split(/[,;]/).filter(function (s) { return s.trim(); }); rows.push([lv.length && lv.some(function (l) { return all.indexOf(l.trim()) >= 0; }) ? 'ok' : 'mid', 'The steps refer to the IV values you set in stage 4.']);
