  /* ---------- 6. Safety and ethics ---------- */
  var SAFE = [['bio', 'Does it use biological materials (plant or animal tissue, food)?', 'Use materials from a supplier or supermarket; wash hands; dispose of tissue as school policy says.'], ['micro', 'Does it involve culturing microorganisms?', 'Only non-pathogenic organisms from a school supplier, aseptic technique, sealed plates, incubation at or below 30 °C, autoclaving. Needs teacher approval.', true], ['human', 'Does it involve human participants (including you)?', 'Informed written consent, right to withdraw, no physical or psychological risk, anonymous data, no body fluids. Needs teacher approval.', true], ['animal', 'Does it involve animals?', 'IB animal experimentation policy: no experiments that harm or stress vertebrates or cephalopods; observation only; invertebrates handled with care and returned. Needs teacher approval.', true], ['chem', 'Does it use hazardous chemicals?', 'Check the safety data sheet; use the lowest concentration that works; eye protection; know the first aid.'], ['field', 'Is there field work or environmental impact?', 'Minimise disturbance, return organisms, permission from the landowner, a buddy system and weather and tide checks.'], ['consent', 'Do you need anyone\'s consent or permission?', 'Get it in writing before you start.'], ['conf', 'Will you collect personal data?', 'Keep it anonymous and stored securely; delete it when finished.'], ['waste', 'Does it produce waste that needs special disposal?', 'Plan disposal of chemicals, cultures and sharps with your teacher.']];
